      body: "\n                   \n\n\n\n\n\n\n\n\n\n\n\n\n\n  Injectables\n  SegmentMembershipSchedulerService\n\n\n\n        \n            Info\n        \n        \n            Source\n        \n\n\n\n    \n        \n            File\n        \n        \n            apps/segment/src/services/segment-membership-scheduler.service.ts\n        \n\n\n\n\n\n            \n    Index\n    \n        \n\n                \n                    \n                        Methods\n                    \n                \n                \n                    \n                        \n                            \n                                    \n                                    Async\n                                flushTransactionEventBatch\n                            \n                            \n                                    \n                                    Async\n                                recomputeDynamicSegments\n                            \n                        \n                    \n                \n\n\n\n\n\n        \n    \n\n\n            \n    Constructor\n        \n            \n                \n                    \nconstructor(segmentMembershipService: SegmentMembershipService)\n                    \n                \n                        \n                            \n                                Defined in apps/segment/src/services/segment-membership-scheduler.service.ts:10\n                            \n                        \n\n                \n                    \n                            \n                                    Parameters :\n                                    \n                                        \n                                            \n                                                Name\n                                                    Type\n                                                Optional\n                                            \n                                        \n                                        \n                                                \n                                                        segmentMembershipService\n                                                  \n                                                        \n                                                                        SegmentMembershipService\n                                                        \n                                                  \n                                                    \n                                                            No\n                                                    \n                                                    \n                                                \n                                        \n                                    \n                            \n                    \n                \n            \n        \n\n\n            \n    \n    \n        Methods\n    \n    \n        \n            \n                \n                    \n                    \n                            \n                            Async\n                        flushTransactionEventBatch\n                        \n                    \n                \n            \n            \n                \n                        \n                    flushTransactionEventBatch()\n                \n            \n\n            \n                \n                    Decorators : \n                    \n                    @Cron(SEGMENT_EVENT_FLUSH_CRON)\n                \n            \n\n                    \n                        \n                            Defined in apps/segment/src/services/segment-membership-scheduler.service.ts:21\n                        \n                    \n\n\n            \n                \n\n                        \n                            Returns :     Promise\n\n                        \n                \n            \n        \n    \n    \n        \n            \n                \n                    \n                    \n                            \n                            Async\n                        recomputeDynamicSegments\n                        \n                    \n                \n            \n            \n                \n                        \n                    recomputeDynamicSegments()\n                \n            \n\n            \n                \n                    Decorators : \n                    \n                    @Cron(SEGMENT_RECOMPUTE_CRON)\n                \n            \n\n                    \n                        \n                            Defined in apps/segment/src/services/segment-membership-scheduler.service.ts:16\n                        \n                    \n\n\n            \n                \n\n                        \n                            Returns :     Promise\n\n                        \n                \n            \n        \n    \n\n\n    \n\n\n    \n        import { Injectable } from '@nestjs/common';\nimport { Cron } from '@nestjs/schedule';\nimport {\n  SEGMENT_EVENT_FLUSH_CRON,\n  SEGMENT_RECOMPUTE_CRON,\n} from '../constants/constants';\nimport { SegmentMembershipService } from './segment-membership.service';\n\n@Injectable()\nexport class SegmentMembershipSchedulerService {\n  constructor(\n    private readonly segmentMembershipService: SegmentMembershipService,\n  ) {}\n\n  @Cron(SEGMENT_RECOMPUTE_CRON)\n  async recomputeDynamicSegments(): Promise {\n    await this.segmentMembershipService.recomputeAllDynamicMemberships();\n  }\n\n  @Cron(SEGMENT_EVENT_FLUSH_CRON)\n  async flushTransactionEventBatch(): Promise {\n    await this.segmentMembershipService.recomputeMembershipsForPendingTransactionBatch();\n  }\n}\n\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n",
